starterCode.css:
body { margin: 0; font-family: system-ui, sans-serif; background: #e9eef5; color: #172033; }
.dashboard { max-width: 920px; margin: 32px auto; padding: 16px; }
.resumen, .card, .detalle article { border: 1px solid #ccd6e4; background: white; border-radius: 8px; padding: 18px; }
.resumen { background: #123047; color: white; }
.card strong, .detalle strong { display: block; margin-top: 8px; font-size: 1.5rem; }
.detalle { margin-top: 0; }

targetCode.css:
body { margin: 0; font-family: system-ui, sans-serif; background: #e9eef5; color: #172033; }
.dashboard { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 16px; max-width: 920px; margin: 32px auto; padding: 16px; }
.resumen, .card, .detalle article { border: 1px solid #ccd6e4; background: white; border-radius: 8px; padding: 18px; }
.resumen { grid-column: 1 / -1; background: #123047; color: white; }
.card strong, .detalle strong { display: block; margin-top: 8px; font-size: 1.5rem; }
.detalle { display: grid; grid-column: 1 / -1; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 12px; margin-top: 0; }
@media (max-width: 640px) { .dashboard { grid-template-columns: 1fr; } }
